import assert from 'node:assert/strict';import {createVecnaGraftsEngine} from './vecna-grafts-native.mjs';import *as model from '../../src/data/lib/vecna-grafts.js';
export function readyNativeVecnaPair(options={}){const e=createVecnaGraftsEngine(options);let state=model.createVecnaGrafts();for(const [index,profile]of ['current-eye','current-hand'].entries()){const source=e.c.vecnaGraftSourceForRow(e.c.B.inv[index],index,profile,state);assert.equal(source.ok,true);let next=model.admitVecnaGraft(state,{profile,part:source.part,itemFingerprint:source.itemFingerprint},{actualPhysicalArtifactIdentityVerified:true,actualCurrentOriginalSourceVerified:true});assert.equal(next.ok,true);state=next.state;e.c.B.inv[index].vecnaGraft={v:1,id:next.id};next=model.recordVecnaAttachment(state,next.id,{actualPhysicalIdentityVerified:true,[index===0?'actualEyeFusedIntoThisCharactersSocket':'actualHandGraftedOntoThisCharactersLeftStump']:true,printedRemovalConsequenceAcknowledged:true});assert.equal(next.ok,true);state=next.state;}e.c.S.vecnaGrafts=state;e.setC(e.project());return e}
